```typescript
function flattenAndSortEvens(arr: any[]): number[] {
  // Özyinelemeli yardımcı fonksiyon: iç içe dizileri düzleştirir
  const flatten = (input: any[]): number[] => {
    if (!Array.isArray(input)) return [input];

    return input.reduce<number[]>((acc, item) => {
      if (Array.isArray(item)) {
        acc.push(...flatten(item));
      } else {
        acc.push(item);
      }
      return acc;
    }, []);
  };

  // Düzleştirilmiş diziden çift sayıları al
  const evens = flatten(arr).filter(num => typeof num === 'number' && num % 2 === 0);

  // Büyükten küçüğe sırala
  return evens.sort((a, b) => b - a);
}
```

