```typescript
function distinctOrderPreserving(arr: number[]): number[] {
  const seen = new Set<number>();
  const result: number[] = [];

  for (const value of arr) {
    if (!seen.has(value)) {
      seen.add(value);
      result.push(value);
    }
  }

  return result;
}
```

